\section{The tensor code test}
\label{sec:test}

Let $\code$ be an interpolable code (called the \emph{base code}) over alphabet $\Sigma$ with blocklength $n$, dimension $k$, and distance $d$, and let $m \geq 2$ be an integer. Informally, the augmented tensor code test proceeds as follows. With probability $1/2$, the referee performs the line-vs-point test as described in the introduction. With probability $1/2$, the referee performs a \emph{subcube commutation test}. 
Here, a \emph{subcube} of $[n]^m$ denotes a subset of points of the form $H_{x_{m-j+2},\ldots,x_{m}} = \{ (x_1,\ldots,x_{m-j+1},x_{m-j+2},\ldots,x_m) \in [n]^m : x_{1},\ldots,x_{m-j+1} \in [n] \}$ where $x_{m-j+2},\ldots,x_{m}$ are fixed elements of $[n]$. If $j = 1$, then we define the subcube $H$ to be all of $[n]^m$.
The purpose of the subcube commutation test is to enforce that for an average subcube $H_{x_{m-j+2},\ldots,x_{m}}$, the measurements corresponding to two randomly chosen points $u,v \in H_{x_{m-j+2},\ldots,x_{m}}$ approximately commute. The motivation for choosing the specific distribution on pairs of points used in the test comes from its use in the analysis, and in particular on how the induction is structured; see the induction step in the proof of Lemma~\ref{lem:induction}. 

The augmented tensor code test for the tensor code $\code^{\otimes m}$ is described precisely in \Cref{fig:test}. From here on we omit the qualifier ``augmented'' and simply refer to the test described in \Cref{fig:test} as the tensor code test.


\begin{definition}\label{def:tracial-strat}
A \emph{tracial strategy} $\strategy$ for the tensor code test is a tuple $(\tau,A,B,P)$ where $\tau: \algebra \to \C$ is a tracial state on a von Neumann algebra $\algebra$, and $A,B,P$ are the following projective measurements:
\begin{enumerate}
	\item \emph{Points measurements}: for every $u \in [n]^m$, let $A^u = \{A^u_a\}_{a \in \Sigma}$ denote the measurement corresponding to the points question $u$.
	\item \emph{Lines measurements}: for every axis-parallel line $\ell \subset [n]^m$, let $B^\ell = \{B^\ell_g\}_{g \in \code}$ denote the measurement corresponding to the lines question $\ell$.
	\item \emph{Pair measurements}: for every subcube $H$ and for every $u,v \in H$, let $P^{u,v} = \{P^{u,v}_{a,b} \}_{a,b\in \Sigma}$ denote the measurement corresponding to the points pair question $(u,v)$.
\end{enumerate}
\end{definition}

Aside from the discussion in Section~\ref{sec:general-states} all strategies considered in the paper are tracial strategies as defined in Definition~\ref{def:tracial-strat}, and we simply say ``strategy'', omitting the qualifier ``tracial''. 

\begin{definition}\label{def:tracial-good}
We say that $\strategy$ is an $(\eps,\delta)$-good (tracial) strategy if the following hold:
\begin{enumerate}
	\item \emph{(Consistency between points and lines:)}
%	\[
%		\E_{u,\ell} \sum_g \tau \paren{ L^\ell_g \, A^u_{g(u)} } \geq 1 - \eps
%	\]
	\[
		B^\ell_{[g \mapsto g(u) | a]} \simeq_\eps A^u_a\;,
	\]
	where the expectation is over a uniformly random axis-parallel line $\ell \subset [n]^m$ and a uniformly random point $u \in \ell$, and the answer summation is over values $a \in \Sigma$. We wrote $g(u)$ to denote $g(u_j)$ where $\ell$ varies in the $j$-th coordinate.% $j$-th direction.

	\item \emph{(Consistency between points and pairs:)}
	\[
		P^{u,v}_{[(a,b) \mapsto a |a]} \simeq_\delta A^u_a \qquad \text{and} \qquad  P^{u,v}_{[(a,b) \mapsto b |b]} \simeq_\delta A^v_b\;,
	\]
%	\[
%		\E_H \E_{u,v \sim H} \sum_{a,b} \tau \paren{B^{u,v}_{a,b} \, A^u_a } \geq 1 - \delta
%	\]
where the expectation is over a uniformly random subcube $H = H_{x_{m-j+2},\ldots,x_{m}}$ (sampled by choosing a random $j \sim [m]$ and random $x_{m-j+2},\ldots,x_{m} \sim [n]$) and uniformly random points $u,v \sim H$, and the answer summation is over values $a \in \Sigma$ and $b \in \Sigma$ respectively.
\end{enumerate}
\end{definition}


